// GENERATED by scripts/sync-shared.ts from shared/prices.ts. Edit shared/, not this copy.
// Official list prices, USD per MTok. Source: research/12d-subscription-economics.md s2, from
// https://platform.claude.com/docs/en/about-claude/pricing. AS OF 2026-10-11. Estimates, never invoices.
// No network lookup, ever. Overridable via the plugin-level `pricesJson` userConfig (parsePricesJson).
import { modelFamily } from './fmt'
import type { ModelFamily } from './fmt'

export const PRICES_AS_OF = '2026-10-11'
export const PRICES_SOURCE = 'https://platform.claude.com/docs/en/about-claude/pricing (research/12d s2)'

export type PriceRow = { family: ModelFamily; id: string; input: number; output: number; cacheRead: number; write5m: number; write1h: number }

const row = (family: ModelFamily, id: string, input: number, output: number, cacheRead: number, write5m: number, write1h: number): PriceRow => ({ family, id, input, output, cacheRead, write5m, write1h })

/** Rows in match order (regex on the model id, see rowFor). */
export const PRICE_TABLE: readonly PriceRow[] = [
  row('fable', 'fable-5.1', 10, 50, 0.25, 12.5, 20),
  row('opus', 'opus-5.5', 4, 20, 0.2, 5, 8),
  row('opus', 'opus-5', 5, 25, 0.5, 6.25, 10),
  row('sonnet', 'sonnet-5.5', 2, 10, 0.1, 2.5, 4),
  // Sonnet 5 base row not tabulated in 12d s2: uses the Sonnet 5.5 row.
  // Haiku 5.5, prompt <= 100k. Over 100k see HAIKU_OVER_100K.
  row('haiku', 'haiku-5.5', 0.1, 0.5, 0.01, 0.125, 0.2),
]
export const HAIKU_OVER_100K: PriceRow = row('haiku', 'haiku-5.5>100k', 0.5, 2.5, 0.05, 0.625, 1)
/** Used for unknown models; callers add ` (default price)`. Opus 5.5 row. */
export const DEFAULT_ROW: PriceRow = PRICE_TABLE[1] as PriceRow

export type PriceOverride = Partial<Pick<PriceRow, 'input' | 'output' | 'cacheRead' | 'write5m' | 'write1h'>>
export type PriceOverrides = { asOf?: string; byFamily: Partial<Record<ModelFamily, PriceOverride>> }

/** Parses the `pricesJson` option; invalid JSON or shapes -> `{ok:false}` (caller logs once, keeps the built-in table). Unknown keys ignored. */
export function parsePricesJson(s: string | undefined): { ok: true; overrides: PriceOverrides } | { ok: false } {
  if (!s || !s.trim()) return { ok: true, overrides: { byFamily: {} } }
  try {
    const parsed = JSON.parse(s) as unknown
    if (Array.isArray(parsed)) {
      // Table row shape: [family, input, output, cacheRead, write5m, write1h, asOf?] in $/MTok.
      const byFam: PriceOverrides['byFamily'] = {}
      let asOf: string | undefined
      for (const r of parsed) {
        if (!Array.isArray(r) || typeof r[0] !== 'string') return { ok: false }
        const fam = r[0].toLowerCase() as ModelFamily
        const nums = r.slice(1, 6)
        if (nums.length < 5 || nums.some(n => typeof n !== 'number' || !isFinite(n) || n < 0)) return { ok: false }
        byFam[fam] = { input: nums[0], output: nums[1], cacheRead: nums[2], write5m: nums[3], write1h: nums[4] }
        if (typeof r[6] === 'string') asOf = r[6]
      }
      return { ok: true, overrides: { asOf, byFamily: byFam } }
    }
    const j = parsed as Record<string, unknown>
    if (!j || typeof j !== 'object' || Array.isArray(j)) return { ok: false }
    const byFamily: PriceOverrides['byFamily'] = {}
    for (const fam of ['fable', 'opus', 'sonnet', 'haiku', 'other'] as const) {
      const v = j[fam]
      if (v && typeof v === 'object') {
        const o: PriceOverride = {}
        for (const k of ['input', 'output', 'cacheRead', 'write5m', 'write1h'] as const) {
          const n = (v as Record<string, unknown>)[k]
          if (typeof n === 'number' && isFinite(n) && n >= 0) o[k] = n
        }
        byFamily[fam] = o
      }
    }
    return { ok: true, overrides: { asOf: typeof j.asOf === 'string' ? j.asOf : undefined, byFamily } }
  } catch {
    return { ok: false }
  }
}

/** Row for a model id (and prompt size for Haiku tiering), with overrides applied by family. */
export function rowFor(model: string | undefined, o: { overrides?: PriceOverrides; promptTokens?: number } = {}): { row: PriceRow; isDefault: boolean; isCustom: boolean } {
  const id = String(model ?? '').toLowerCase()
  let base: PriceRow | undefined
  let isDefault = false
  if (/fable/.test(id)) base = PRICE_TABLE[0]
  else if (/opus-5[-.]5/.test(id)) base = PRICE_TABLE[1]
  else if (/opus-5(?![-.]?\d)/.test(id)) base = PRICE_TABLE[2]
  else if (/sonnet/.test(id)) base = PRICE_TABLE[3]
  else if (/haiku/.test(id)) base = (o.promptTokens ?? 0) > 100_000 ? HAIKU_OVER_100K : PRICE_TABLE[4]
  if (!base) { base = DEFAULT_ROW; isDefault = true }
  const ov = o.overrides?.byFamily[isDefault ? modelFamily(id) : base.family]
  if (ov) return { row: { ...base, ...ov }, isDefault, isCustom: true }
  return { row: base, isDefault, isCustom: false }
}

type PO = { overrides?: PriceOverrides; promptTokens?: number }
/** USD per MTok. */
export const price = (model: string | undefined, o: PO = {}): PriceRow => rowFor(model, o).row
export const writePrice = (model: string | undefined, ttl: '5m' | '1h', o: PO = {}): number => {
  const r = rowFor(model, o).row
  return ttl === '1h' ? r.write1h : r.write5m
}

export type Usage = { input_tokens?: number; output_tokens?: number; cache_read_input_tokens?: number; cache_creation_input_tokens?: number }
/** Cost of one request. Cache writes priced at the 5m rate unless `ttl` is '1h'. */
export function stepCostUsd(usage: Usage, model: string | undefined, o: PO & { ttl?: '5m' | '1h' } = {}): number {
  const inT = usage.input_tokens ?? 0
  const rd = usage.cache_read_input_tokens ?? 0
  const wr = usage.cache_creation_input_tokens ?? 0
  const r = rowFor(model, { ...o, promptTokens: o.promptTokens ?? inT + rd + wr }).row
  const w = o.ttl === '1h' ? r.write1h : r.write5m
  return (inT * r.input + (usage.output_tokens ?? 0) * r.output + rd * r.cacheRead + wr * w) / 1e6
}

/** Re-cache cost of `ctxTokens` at the write rate. */
export const recacheUsd = (ctxTokens: number, model: string | undefined, ttl: '5m' | '1h', o: PO = {}): number =>
  (ctxTokens * writePrice(model, ttl, { ...o, promptTokens: o.promptTokens ?? ctxTokens })) / 1e6

/** Dollars a cache read saved vs uncached input, minus the write premium paid (usage.md "Savings today"). */
export function savedUsd(usage: Usage, model: string | undefined, o: PO & { ttl?: '5m' | '1h' } = {}): number {
  const r = rowFor(model, { ...o, promptTokens: o.promptTokens ?? (usage.input_tokens ?? 0) + (usage.cache_read_input_tokens ?? 0) + (usage.cache_creation_input_tokens ?? 0) }).row
  const w = o.ttl === '1h' ? r.write1h : r.write5m
  return ((usage.cache_read_input_tokens ?? 0) * (r.input - r.cacheRead) - (usage.cache_creation_input_tokens ?? 0) * (w - r.input)) / 1e6
}

/** Footer label: `estimate (prices as of 2026-10-11)` or `estimate (prices as of <asOf>, custom)`. */
export function priceLabel(overrides?: PriceOverrides, hasCustom = false): string {
  const custom = hasCustom || (overrides != null && Object.keys(overrides.byFamily).length > 0)
  return custom ? `estimate (prices as of ${overrides?.asOf ?? PRICES_AS_OF}, custom)` : `estimate (prices as of ${PRICES_AS_OF})`
}
